package br.com.confirmacao.admin.api;
import br.com.confirmacao.admin.application.AdminPatientService;import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.audit.domain.AuditAction;import br.com.confirmacao.patient.api.*;import br.com.confirmacao.professional.api.*;import br.com.confirmacao.professional.application.ProfessionalService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/admin") public class AdminWriteController{private final ProfessionalService professionals;private final AdminPatientService patients;private final AuditService audit;public AdminWriteController(ProfessionalService p,AdminPatientService x,AuditService a){professionals=p;patients=x;audit=a;}@PutMapping("/professionals/{id}")public ProfessionalResponse updateProfessional(@PathVariable UUID id,@Valid@RequestBody UpdateProfessionalRequest r,HttpServletRequest h){var current=professionals.findById(id);var p=professionals.updateProfile(id,r.fullName(),r.email(),r.phone(),r.registrationNumber(),r.specialty()==null?current.getSpecialty():r.specialty(),current.getDisplayName(),current.getTimezone(),current.getDefaultSessionMinutes(),current.getDefaultModality(),current.isRemindersEnabled());audit.record(AuditAction.PROFESSIONAL_UPDATED,"PROFESSIONAL",id,h);return ProfessionalResponse.from(p);}@DeleteMapping("/professionals/{id}")public ResponseEntity<Void> deactivateProfessional(@PathVariable UUID id,HttpServletRequest h){professionals.deactivate(id);audit.record(AuditAction.PROFESSIONAL_DEACTIVATED,"PROFESSIONAL",id,h);return ResponseEntity.noContent().build();}@PatchMapping("/professionals/{id}/activate")public ResponseEntity<Void> activateProfessional(@PathVariable UUID id,HttpServletRequest h){professionals.activate(id);audit.record(AuditAction.PROFESSIONAL_ACTIVATED,"PROFESSIONAL",id,h);return ResponseEntity.noContent().build();}@PutMapping("/patients/{id}")public PatientResponse updatePatient(@PathVariable UUID id,@Valid@RequestBody UpdatePatientRequest r,HttpServletRequest h){var p=patients.update(id,r.fullName(),r.birthDate(),r.phone(),r.email(),r.preferredChannel(),r.whatsappRemindersEnabled());audit.record(AuditAction.PATIENT_UPDATED,"PATIENT",id,h);return PatientResponse.from(p);}@DeleteMapping("/patients/{id}")public ResponseEntity<Void> deactivatePatient(@PathVariable UUID id,HttpServletRequest h){patients.deactivate(id);audit.record(AuditAction.PATIENT_DEACTIVATED,"PATIENT",id,h);return ResponseEntity.noContent().build();}@PatchMapping("/patients/{id}/activate")public ResponseEntity<Void> activatePatient(@PathVariable UUID id,HttpServletRequest h){patients.activate(id);audit.record(AuditAction.PATIENT_ACTIVATED,"PATIENT",id,h);return ResponseEntity.noContent().build();}}
